const CATEGORY_NAME = Object.fromEntries(CATEGORIES.map((category) => [category.id, category.name]))
export const TOOL = Object.fromEntries(TOOLS.map((tool) => [tool.id, tool])) as Record<
  string,
  PdfTool
>

/** Every word must appear in the name, description, category, aliases or id; name hits rank first. */
export function searchTools(query: string): PdfTool[] {
  const words = query.toLowerCase().trim().split(/\s+/).filter(Boolean)
  if (!words.length) return TOOLS
  return TOOLS.map((tool) => {
    const name = `${tool.name} ${tool.name}`.toLowerCase()
    const haystack =
      `${name} ${tool.desc} ${CATEGORY_NAME[tool.category]} ${tool.aliases.join(' ')} ${tool.id}`.toLowerCase()
    if (!words.every((word) => haystack.includes(word))) return null
    const score = words.reduce(
      (sum, word) => sum + (name.startsWith(word) ? 3 : name.includes(word) ? 2 : 1),
      0,
    )
    return { tool, score }
  })
    .filter((entry): entry is { tool: PdfTool; score: number } => entry !== null)
    .sort((a, b) => b.score - a.score)
    .map(({ tool }) => tool)
}

export function categoryCount(tools: PdfTool[], category: Category) {
  return tools.filter((tool) => tool.category === category).length
}

const TOKEN = /^(\d*)(-?)(\d*)$/

/** Zero-based pages from "1-3, 5, 8-"; null when the text is not a valid selection. */
export function parsePageSelection(input: string, total: number): number[] | null {
  const tokens = input
    .replace(/\s*[-–]\s*/g, '-')
    .split(/[,;\s]+/)
    .filter(Boolean)
  if (!tokens.length) return null
  const pages: number[] = []
  for (const token of tokens) {
    const match = TOKEN.exec(token)
    if (!match || (!match[1] && !match[3]) || (!match[2] && !match[1])) return null
    const start = match[1] ? Number(match[1]) : 1
    const end = match[2] ? (match[3] ? Number(match[3]) : total) : start
    if (start < 1 || end < 1 || start > total || end > total) return null
    const step = start <= end ? 1 : -1
    for (let page = start; page !== end + step; page += step) pages.push(page - 1)
  }
  return [...new Set(pages)]
}

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 ** 2) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / 1024 ** 2).toFixed(2)} MB`
}

